#pragma once

// Compact storage extends Position v3. Dense entries include no part of
// this header, so their source closure and generated bytes stay unchanged.
#include "pooled_indexer/position.cuh"

namespace chop::position_blocks {
using namespace position_indexer;

// Controls are lab-only: 1 ignores order/duplicates, 2 ignores provenance,
// 3 ignores the newest-block requirement. Production always uses zero.
template<int Heads, int Dim, int Page, int Ratio, int Block, int Kept, int Control = 0>
__device__ void scores(
    const uint16_t* queries, const float* weights, const uint8_t* codes,
    const uint8_t* scales, const int32_t* tables, const int32_t* batches,
    const int32_t* positions, const uint32_t* live_rows, const int32_t* ids,
    const uint64_t* tags, const uint64_t* stored_tags, const int32_t* stored_visible,
    const int32_t* source_status, float* output, uint32_t width,
    uint32_t max_pages, uint64_t code_stride, uint64_t scale_stride, float weight_scale) {
  static_assert(Dim > 0 && Dim % 32 == 0);
  ptx::griddep_launch_dependents();
  ptx::griddep_wait();
  const uint32_t row = blockIdx.y;
  const uint32_t slot = blockIdx.x * 4 + threadIdx.x / 32;
  const uint32_t lane = threadIdx.x & 31;
  if (row >= *live_rows || slot >= Block * Kept) return;
  const uint32_t count = min(visible(positions[row], Ratio), width);
  const int32_t id = ids[size_t(row) * Kept + slot / Block];
  const uint64_t mapped = id < 0 ? uint64_t(width) : uint64_t(id) * Block + slot % Block;
  float* out = output + size_t(row) * (Block * Kept) + slot;
  if (source_status[row] != 0 || (Control != 2 && (tags[row] != stored_tags[row] || stored_visible[row] != int32_t(count))) || mapped >= count) {
    if (lane == 0) *out = -__int_as_float(0x7f800000);
    return;
  }
  const uint32_t index = uint32_t(mapped);
  const int32_t* table = tables + size_t(batches[row]) * max_pages;
  if (!admitted<Page, false>(index, count, nullptr, table)) {
    if (lane == 0) *out = -__int_as_float(0x7f800000);
    return;
  }
  // Keep the admitted-position arithmetic identical to position.cuh:
  // same decoded values, 128-channel chains, trees and head FMA order.
  const uint32_t page = uint32_t(table[index / Page]);
  const uint8_t* key_codes = codes + uint64_t(page) * code_stride + size_t(index % Page) * (Dim / 2);
  const uint8_t* key_scales = scales + uint64_t(page) * scale_stride + size_t(index % Page) * (Dim / 32);
  float key[Dim / 32];
  bool invalid = false;
#pragma unroll
  for (int part = 0; part < Dim / 32; ++part) {
    const int channel = part * 32 + lane;
    const uint32_t pair = convert::scaled_mxfp4_bf16x2<false>(key_codes[channel / 2], key_scales[part]);
    key[part] = bf16(uint16_t(pair >> (((channel ^ false) & 1) * 16)));
    invalid |= key_scales[part] == 255 || !isfinite(key[part]);
  }
  float result = 0.f;
#pragma unroll 1
  for (int head = 0; head < Heads; ++head) {
    const uint16_t* q = queries + (size_t(row) * Heads + head) * Dim;
    float dot = 0.f;
#pragma unroll
    for (int base = 0; base < Dim; base += 128) {
      float chain = 0.f;
#pragma unroll
      for (int part = base / 32; part < (base + 128 < Dim ? base + 128 : Dim) / 32; ++part) {
        const float value = bf16(q[part * 32 + lane]);
        invalid |= !isfinite(value);
        chain = fmaf(value, key[part], chain);
        invalid |= !isfinite(chain);
      }
#pragma unroll
      for (int offset = 16; offset > 0; offset >>= 1) {
        chain += __shfl_down_sync(0xffffffffu, chain, offset);
        // Only these lanes feed the next level of the reduction tree.
        invalid |= lane < offset && !isfinite(chain);
      }
      dot += chain;
      invalid |= lane == 0 && !isfinite(dot);
    }
    if (lane == 0) {
      const int weight_head = head;
      const float weight = __fmul_rn(weights[size_t(row) * Heads + weight_head], weight_scale);
      invalid |= !isfinite(weight);
      result = fmaf(dot > 0.f ? dot : 0.f, weight, result);
      invalid |= !isfinite(result);
    }
  }
  const bool failed = __any_sync(0xffffffffu, invalid);
  if (lane == 0) *out = failed ? __int_as_float(0x7fc00000) : result;
}

// One CTA validates and selects a row. Validation costs no extra launch.
template<int Page, int Ratio, int MaxTopK, int Block, int Kept, int Control = 0>
__device__ void select(
    float* scores, const int32_t* tables, const int32_t* batches,
    const int32_t* positions, const uint32_t* live_rows, const int32_t* ids,
    const uint64_t* tags, const uint64_t* stored_tags, const int32_t* stored_visible,
    const int32_t* source_status, int32_t* output, int32_t* status,
    uint32_t width, uint32_t max_pages, uint32_t top_k) {
  __shared__ uint32_t histogram[threads], rank, scan[threads], written;
  __shared__ uint64_t prefix;
  ptx::griddep_launch_dependents();
  ptx::griddep_wait();
  const uint32_t row = blockIdx.x;
  if (row >= *live_rows) return;
  const uint32_t count = min(visible(positions[row], Ratio), width);
  const int32_t* row_ids = ids + size_t(row) * Kept;
  const int32_t* table = tables + size_t(batches[row]) * max_pages;
  float* values = scores + size_t(row) * (Block * Kept);
  int invalid = source_status[row] != 0 || (Control != 2 && (tags[row] != stored_tags[row] || stored_visible[row] != int32_t(count)));
  int pinned = count == 0;
  for (uint32_t i = threadIdx.x; i < Kept; i += threads) {
    const int32_t id = row_ids[i];
    if (id == -1) continue;
    invalid |= id < 0 || uint64_t(id) * Block >= count;
    if constexpr (Control != 1) invalid |= i > 0 && (row_ids[i - 1] < 0 || row_ids[i - 1] >= id);
    pinned |= count > 0 && id == int32_t((count - 1) / Block);
  }
  const int has_pin = __syncthreads_or(pinned);
  if constexpr (Control != 3) invalid |= !has_pin;
  const int malformed = __syncthreads_or(invalid);
  auto index = [&](uint32_t slot) -> uint32_t {
    const int32_t id = row_ids[slot / Block];
    const uint64_t mapped = id < 0 ? uint64_t(width) : uint64_t(id) * Block + slot % Block;
    return mapped < count ? uint32_t(mapped) : width;
  };
  for (uint32_t slot = threadIdx.x; slot < Block * Kept; slot += threads) {
    if (malformed) values[slot] = -__int_as_float(0x7f800000);
    else if (admitted<Page, false>(index(slot), count, nullptr, table) && !isfinite(values[slot])) {
      invalid = 1;
      values[slot] = -__int_as_float(0x7f800000);
    }
  }
  const int failed = __syncthreads_or(invalid) != 0;
  if (threadIdx.x == 0) status[row] = failed;
  int32_t* out = output + size_t(row) * MaxTopK;
  for (int i = threadIdx.x; i < MaxTopK; i += threads) out[i] = -1;
  if (failed) return;
  auto key = [&](uint32_t slot) -> uint64_t {
    const uint32_t i = index(slot);
    return admitted<Page, false>(i, count, nullptr, table) ? candidate_key(values[slot], i) : uint64_t(0);
  };
  const uint64_t threshold = cutoff(Block * Kept, top_k, key, histogram, &prefix, &rank);
  if (threadIdx.x == 0) written = 0;
  __syncthreads();
  for (uint32_t base = 0; base < Block * Kept; base += threads) {
    const uint32_t slot = base + threadIdx.x;
    const uint64_t value = slot < Block * Kept ? key(slot) : 0;
    const bool keep = value != 0 && value >= threshold;
    scan[threadIdx.x] = keep;
    __syncthreads();
    for (int distance = 1; distance < threads; distance *= 2) {
      const uint32_t add = threadIdx.x >= distance ? scan[threadIdx.x - distance] : 0;
      __syncthreads();
      scan[threadIdx.x] += add;
      __syncthreads();
    }
    // The bound also keeps lab mutants with duplicate tie keys memory-safe.
    if (keep && written + scan[threadIdx.x] <= top_k)
      out[written + scan[threadIdx.x] - 1] = int32_t(index(slot));
    __syncthreads();
    if (threadIdx.x == 0) written += scan[threads - 1];
    __syncthreads();
  }
}

// Preserve the dense maximum and pinning arithmetic on valid scores. NaN
// is an error marker in scratch, including when the bad score is in the
// pinned block. The row gather turns any marker into status 1 and empty IDs.
// No device value can trap, and no extra scratch or status initialization
// launch is needed.
template<int Block>
__device__ void block_scores(const float* scores, const int32_t* visible_counts,
                             const uint32_t* live_rows, float* blocks, uint32_t width) {
  ptx::griddep_launch_dependents();
  ptx::griddep_wait();
  const uint32_t row = blockIdx.y;
  const uint32_t block = blockIdx.x * threads + threadIdx.x;
  const uint32_t block_count = (width + Block - 1) / Block;
  if (row >= *live_rows || block >= block_count) return;
  const int32_t requested = visible_counts[row];
  const uint32_t count = min(uint32_t(max(requested, 0)), width);
  bool invalid = requested < 0 || uint32_t(requested) > width;
  float value = -__int_as_float(0x7f800000);
#pragma unroll
  for (int offset = 0; offset < Block; ++offset) {
    const uint32_t i = block * Block + offset;
    if (!invalid && i < count) {
      const float score = scores[size_t(row) * width + i];
      invalid |= isnan(score) || score == __int_as_float(0x7f800000);
      value = fmaxf(value, score);
    }
  }
  if (count != 0 && block == (count - 1) / Block) value = __int_as_float(0x7f800000);
  blocks[size_t(row) * block_count + block] = invalid ? __int_as_float(0x7fc00000) : value;
}

// Gather replaces block_mask, with identical cutoff and original block keys.
template<int Block, int Kept>
__device__ void gather(
    const float* blocks, const uint32_t* live_rows, const uint64_t* tags,
    const int32_t* visible_counts, const int32_t* source_status,
    int32_t* ids, uint64_t* out_tags, int32_t* out_visible, int32_t* status,
    uint32_t width) {
  __shared__ uint32_t histogram[threads], rank, scan[threads], written;
  __shared__ uint64_t prefix;
  ptx::griddep_launch_dependents();
  ptx::griddep_wait();
  const uint32_t row = blockIdx.x;
  if (row >= *live_rows) return;
  const uint32_t count = min(uint32_t(max(visible_counts[row], 0)), width);
  int32_t* out = ids + size_t(row) * Kept;
  for (int i = threadIdx.x; i < Kept; i += threads) out[i] = -1;
  const uint32_t block_count = (width + Block - 1) / Block;
  const float* values = blocks + size_t(row) * block_count;
  int invalid = source_status[row] != 0;
  for (uint32_t i = threadIdx.x; i < block_count; i += threads) invalid |= isnan(values[i]);
  const int failed = __syncthreads_or(invalid) != 0;
  if (threadIdx.x == 0) {
    out_tags[row] = tags[row];
    out_visible[row] = int32_t(count);
    status[row] = failed;
  }
  if (failed) return;
  auto key = [&](uint32_t i) {
    return values[i] > -__int_as_float(0x7f800000) ? candidate_key(values[i], i) : uint64_t(0);
  };
  const uint64_t threshold = cutoff(block_count, Kept, key, histogram, &prefix, &rank);
  if (threadIdx.x == 0) written = 0;
  __syncthreads();
  for (uint32_t base = 0; base < block_count; base += threads) {
    const uint32_t i = base + threadIdx.x;
    const uint64_t value = i < block_count ? key(i) : 0;
    const bool keep = value != 0 && value >= threshold;
    scan[threadIdx.x] = keep;
    __syncthreads();
    for (int distance = 1; distance < threads; distance *= 2) {
      const uint32_t add = threadIdx.x >= distance ? scan[threadIdx.x - distance] : 0;
      __syncthreads();
      scan[threadIdx.x] += add;
      __syncthreads();
    }
    if (keep) out[written + scan[threadIdx.x] - 1] = int32_t(i);
    __syncthreads();
    if (threadIdx.x == 0) written += scan[threads - 1];
    __syncthreads();
  }
}
}  // namespace chop::position_blocks
